using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Printing;using System.Windows.Forms;
namespace BeamScheduleFormatter {
class SmoothPageBox:PictureBox {protected override void OnPaint(PaintEventArgs e){e.Graphics.InterpolationMode=InterpolationMode.HighQualityBicubic;e.Graphics.PixelOffsetMode=PixelOffsetMode.HighQuality;base.OnPaint(e);}}
class ContinuousPreview:ScrollableControl {
 readonly System.Collections.Generic.List<System.Collections.Generic.List<string>> pages;readonly string heading;float zoom,scale;int pageWidth,pageHeight,lastPage;public event Action<int> PageChanged;public int PageCount{get{return pages.Count;}}
 public ContinuousPreview(string report){pages=EstimatePdf.Pages(report);heading=EstimatePdf.Heading(report);AutoScroll=true;BackColor=Color.FromArgb(90,100,112);DoubleBuffered=true;ResizeRedraw=true;TabStop=true;SetStyle(ControlStyles.Selectable,true);}
 public void SetZoom(float value){int page=CurrentPage();zoom=value;LayoutPages();Jump(page);}
 int CurrentPage(){return Math.Max(1,Math.Min(PageCount,(-AutoScrollPosition.Y+16)/(Math.Max(1,pageHeight)+24)+1));}
 void LayoutPages(){scale=zoom==0?Math.Max(.25f,(ClientSize.Width-48)/595.28f):zoom*96/72f;pageWidth=(int)(595.28f*scale);pageHeight=(int)(841.89f*scale);AutoScrollMinSize=new Size(pageWidth+48,PageCount*(pageHeight+24)+24);Invalidate();}
 public void Jump(int page){AutoScrollPosition=new Point(Math.Max(0,-AutoScrollPosition.X),Math.Max(0,(page-1)*(pageHeight+24)));Invalidate();}
 protected override void OnResize(EventArgs e){base.OnResize(e);LayoutPages();}
 protected override void OnScroll(ScrollEventArgs e){base.OnScroll(e);Invalidate();}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(pageHeight<=0)return;e.Graphics.SmoothingMode=SmoothingMode.HighQuality;e.Graphics.InterpolationMode=InterpolationMode.HighQualityBicubic;e.Graphics.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;for(int i=Math.Max(0,-AutoScrollPosition.Y/(pageHeight+24));i<PageCount;i++){int y=16+i*(pageHeight+24)+AutoScrollPosition.Y;if(y>ClientSize.Height)break;int x=Math.Max(16,(ClientSize.Width-pageWidth)/2)+AutoScrollPosition.X;var state=e.Graphics.Save();try{e.Graphics.SetClip(new Rectangle(x,y,pageWidth,pageHeight));e.Graphics.PageUnit=GraphicsUnit.Point;e.Graphics.TranslateTransform(x*72f/e.Graphics.DpiX,y*72f/e.Graphics.DpiY);e.Graphics.ScaleTransform(scale*72f/e.Graphics.DpiX,scale*72f/e.Graphics.DpiY);CalculationPreview.DrawPage(e.Graphics,pages[i].ToArray(),i+1,PageCount,heading);}finally{e.Graphics.Restore(state);}}int current=CurrentPage();if(current!=lastPage){lastPage=current;if(PageChanged!=null)PageChanged(current);}}
}static class CalculationPreview {
 public static PrintDocument Document(string report){var pages=EstimatePdf.Pages(report);int page=0;var doc=new PrintDocument{DocumentName=EstimatePdf.Heading(report)};doc.DefaultPageSettings.PaperSize=new PaperSize("A4",827,1169);doc.DefaultPageSettings.Landscape=false;doc.BeginPrint+=(s,e)=>page=0;doc.PrintPage+=(s,e)=>{DrawPage(e.Graphics,pages[page].ToArray(),page+1,pages.Count,EstimatePdf.Heading(report));page++;e.HasMorePages=page<pages.Count;};return doc;}
 public static void Show(IWin32Window owner,string report){using(var f=new Form{Text="Print Preview - continuous scrolling",Width=1120,Height=850,MinimumSize=new Size(800,600),StartPosition=FormStartPosition.CenterParent})using(var doc=Document(report)){var view=new ContinuousPreview(report){Dock=DockStyle.Fill};var tools=new FlowLayoutPanel{Dock=DockStyle.Top,Height=46,Padding=new Padding(8),BackColor=Color.White};var print=new Button{Text="Print...",Width=90,Height=28};print.Click+=(s,e)=>{try{using(var dialog=new PrintDialog{Document=doc,UseEXDialog=true})if(dialog.ShowDialog(f)==DialogResult.OK)doc.Print();}catch(Exception ex){MessageBox.Show(f,ex.Message,"Print calculation sheet");}};tools.Controls.Add(print);tools.Controls.Add(new Label{Text="Page",AutoSize=true,Padding=new Padding(4,6,0,0)});var number=new NumericUpDown{Minimum=1,Maximum=view.PageCount,Width=60};tools.Controls.Add(number);tools.Controls.Add(new Label{Text=" / "+view.PageCount+" - scroll through all pages",AutoSize=true,Padding=new Padding(0,6,8,0)});var zoom=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=110};zoom.Items.AddRange(new object[]{"Fit width","50%","75%","100%","125%","150%","200%","300%"});zoom.SelectedIndex=0;zoom.SelectedIndexChanged+=(s,e)=>view.SetZoom(zoom.SelectedIndex==0?0:new[]{0,.5f,.75f,1,1.25f,1.5f,2,3}[zoom.SelectedIndex]);tools.Controls.Add(zoom);bool updating=false;number.ValueChanged+=(s,e)=>{if(!updating)view.Jump((int)number.Value);};view.PageChanged+=page=>{updating=true;number.Value=page;updating=false;};var close=new Button{Text="Close",Width=75,Height=28};close.Click+=(s,e)=>f.Close();tools.Controls.Add(close);f.Controls.Add(view);f.Controls.Add(tools);f.Shown+=(s,e)=>view.Focus();f.ShowDialog(owner);}} public static void DrawPage(Graphics g,string[] lines,int page,int total,string heading=null){var state=g.Save();try{g.PageUnit=GraphicsUnit.Point;g.FillRectangle(Brushes.White,0,0,595.28f,841.89f);PdfBrand.Draw(g);g.DrawLine(Pens.Gray,72,119.89f,559.28f,119.89f);Text(g,heading??"SPLICE, DEVELOPMENT & HOOKS | CALCULATION SHEET",74,30,10,Color.FromArgb(31,46,64));Text(g,"DTCE Tool Kit v"+Engine.Version+" | SI units | Print-only review copy",74,51,8,Color.SlateGray);var project=ProjectInfoStore.Read();Text(g,project.NameLine,74,68,8,Color.FromArgb(31,46,64));Text(g,project.LocationLine,74,82,8,Color.FromArgb(31,46,64));float y=125;foreach(string line in lines){bool section=line.StartsWith("## ");if(section){using(var brush=new SolidBrush(Color.FromArgb(230,240,250)))g.FillRectangle(brush,72,y-1,487.28f,13);g.FillRectangle(Brushes.SteelBlue,72,y-1,2,13);}Text(g,section?line.Substring(3):line,74,y,10f,Color.FromArgb(31,46,64));y+=12;}g.DrawLine(Pens.LightSlateGray,72,807,559.28f,807);Text(g,"Generated "+DateTime.Now.ToString("yyyy-MM-dd")+" | Lengths in mm unless noted",74,811,8,Color.SlateGray);string pageText="Page "+page+" / "+total;Text(g,pageText,(float)(559.28-pageText.Length*ReportFont.Width/1000*8*.85),811,8,Color.SlateGray);}finally{g.Restore(state);}}
 static void Text(Graphics g,string text,float x,float y,float size,Color color){var state=g.Save();try{g.TranslateTransform(x,y);g.ScaleTransform(.85f,1);using(var font=new Font(ReportFont.Family,size,FontStyle.Regular,GraphicsUnit.Point))using(var brush=new SolidBrush(color))g.DrawString(text,font,brush,0,0,StringFormat.GenericTypographic);}finally{g.Restore(state);}}
}
}
